using System;using System.IO;using System.Text;using System.Linq;using Microsoft.Win32;
internal static class UsbHidAdmissionGpoTest {
 const string A=@"USB\VID_0001&PID_0002\A",B=@"USB\VID_0003&PID_0004\B",Owner="S-1-5-21-1-2-3-1000";static int cases;
 static void Check(bool v){if(!v)throw new Exception("HID GPO regression");cases++;}static void Reject(Action action){bool failed=false;try{action();}catch{failed=true;}Check(failed);}
 static void Entry(BinaryWriter w,string key,string name,uint kind,byte[] data){byte[] k=Encoding.ASCII.GetBytes(key),n=Encoding.ASCII.GetBytes(name);w.Write((byte)k.Length);w.Write((byte)n.Length);w.Write(kind);w.Write((ushort)data.Length);w.Write(k);w.Write(n);w.Write(data);}
 static byte[] Plan(string[] ids,bool foreign=false){using(var ms=new MemoryStream())using(var w=new BinaryWriter(ms)){w.Write(Encoding.ASCII.GetBytes("SNTPLAN1"));w.Write((ushort)(5+ids.Length));foreach(string flag in new[]{foreign?"DenyUnspecified":"AllowDenyLayered","AllowInstanceIDs","DenyDeviceIDs","DenyDeviceIDsRetroactive"})Entry(w,"",flag,4,BitConverter.GetBytes(1));Entry(w,"DenyDeviceIDs","1",1,Encoding.Unicode.GetBytes(@"USB\Class_03"+"\0"));for(int i=0;i<ids.Length;i++)Entry(w,"AllowInstanceIDs",(i+1).ToString(),1,Encoding.Unicode.GetBytes(ids[i]+"\0"));w.Flush();return ms.ToArray();}}
 static void Write(RegistryKey root,UsbHidAdmissionGpo.Image image){foreach(var entry in image.Values){int slash=entry.Key.IndexOf('\\');string sub=slash<0?"":entry.Key.Substring(0,slash),name=slash<0?entry.Key:entry.Key.Substring(slash+1);using(var child=sub==""?null:root.CreateSubKey(sub)){var key=child??root;key.SetValue(name,entry.Value,entry.Value is int?RegistryValueKind.DWord:RegistryValueKind.String);}}}
 public static int Main(string[] args){var inactive=new UsbHidAdmissionPolicy.Snapshot(1,Owner,false,new[]{A},new string[0],new string('a',64));var active=new UsbHidAdmissionPolicy.Snapshot(2,Owner,true,new[]{A},new[]{B},new string('a',64));var image=UsbHidAdmissionGpo.Desired(active,Plan(new[]{A,B}));Check(image.Values.Count==8&&image.Values["DenyDeviceIDs\\1"].Equals(@"USB\Class_03")&&(int)image.Values["AllowDenyLayered"]==1);Check(UsbHidAdmissionGpo.Desired(inactive,null).Values.Count==0);Reject(()=>UsbHidAdmissionGpo.Desired(active,Plan(new[]{A})));Reject(()=>UsbHidAdmissionGpo.Desired(active,Plan(new[]{A,B},true)));Reject(()=>UsbHidAdmissionGpo.Desired(inactive,Plan(new[]{A})));var copy=image.Values;copy["AllowDenyLayered"]=0;Check((int)image.Values["AllowDenyLayered"]==1);string nonce=Guid.NewGuid().ToString("N");Reject(()=>new UsbHidAdmissionGpo(@"SOFTWARE\Policies\Microsoft\Windows\DeviceInstall\Restrictions",nonce,()=>{}));
  if(args.Length==1&&args[0]=="--hkcu"){string path=@"Software\SentinelHidAdmissionGpoTests\"+nonce;try{using(var key=Registry.CurrentUser.CreateSubKey(path)){Write(key,image);Check(UsbHidAdmissionGpo.Same(UsbHidAdmissionGpo.ReadPrivateForTest(key,false),image));key.SetValue("DenyUnspecified",1);Reject(()=>UsbHidAdmissionGpo.ReadPrivateForTest(key,false));key.DeleteValue("DenyUnspecified");using(var allows=key.OpenSubKey("AllowInstanceIDs",true)){allows.SetValue("33",A);Reject(()=>UsbHidAdmissionGpo.ReadPrivateForTest(key,false));allows.DeleteValue("33");allows.SetValue("**Del.2","",RegistryValueKind.String);Reject(()=>UsbHidAdmissionGpo.ReadPrivateForTest(key,false));var saved=UsbHidAdmissionGpo.ReadPrivateForTest(key,true);Check(saved.Tombstones.SequenceEqual(new[]{"AllowInstanceIDs\\2"}));allows.DeleteValue("**Del.2");}
    key.SetValue("SentinelOperation",nonce);key.SetValue("DenyInstanceIDs",1);key.SetValue("DenyInstanceIDsRetroactive",1);key.CreateSubKey("DenyInstanceIDs").Dispose();UsbHidAdmissionGpo.ValidateLegacyOverlay(key,image,image,false);Check((int)key.GetValue("DenyInstanceIDs")==1);using(var neutral=key.OpenSubKey("DenyInstanceIDs",true)){neutral.SetValue("1",A);Reject(()=>UsbHidAdmissionGpo.ValidateLegacyOverlay(key,image,image,false));neutral.DeleteValue("1");}key.DeleteValue("SentinelHidAdmissionState");Reject(()=>UsbHidAdmissionGpo.ValidateLegacyOverlay(key,image,image,false));UsbHidAdmissionGpo.ValidateLegacyOverlay(key,image,image,true);
   }}finally{Registry.CurrentUser.DeleteSubKeyTree(path,false);}}
  Console.WriteLine("PASS "+cases+" HID GPO layout/compiler-bind assertions"+(args.Length>0?" and disposable HKCU read/foreign/tombstone/legacy overlay checks":"; no registry operation")+"; no live policy claim");return 0;
 }
